cat >> /tmp/wd_gen/gen.py <<'EOF'

# ---------------- chart data: readings per station, and a decision for every hour -----------------
import yaml
scen = yaml.safe_load(open(REPO / "apps/watch_demo/scenarios.yaml"))["scenarios"]
tz_of = {u["id"]: ZoneInfo(u["timezone"]) for u in users}
station_of = {u["id"]: u["station_id"] for u in users}

def dq(sid, t):
    v, p, n = series[sid].get(t), series[sid].get(t - timedelta(hours=1)), series[sid].get(t + timedelta(hours=1))
    if v is None or p is None or n is None: return None
    if v > 3 * max(p, 1) and v > 3 * max(n, 1) and v - p > 20: return "DQ_SUSPECT"
    return None

readings = {}
for s in scen:
    uid, sid = s["user_id"], station_of[s["user_id"]]
    until = datetime.fromisoformat(s["until"].replace("Z", "+00:00"))
    start = until - timedelta(hours=24)
    for t in sorted(series[sid]):
        if start <= t <= until:
            r = score(sid, t, tz_of[uid]); r["dq"] = dq(sid, t)
            readings.setdefault(sid, {})[r["at"]] = r
    path = OUT / "decisions" / f"{uid}__{s['replay_run']}.json"
    decs = json.loads(path.read_text())
    have = {d["evaluated_at"] for d in decs}
    for t in sorted(series[sid]):
        if start <= t <= until and z(t) not in have:
            decs.append(dec(uid, t, "no_event", "NO_TRIGGER", "Normal for this hour."))
    decs.sort(key=lambda d: d["evaluated_at"])
    path.write_text(json.dumps(decs, indent=2, ensure_ascii=False) + "\n")
for sid, rs in readings.items():
    dump(f"readings/{sid}.json", [rs[k] for k in sorted(rs)])
EOF
