            request,
            sc,
            view="why",
            user=user,
            n=n,
            ago=relative(n.shown_at, now),
            lines=why_lines(n, ex, user),
            decision=ex.decision,
            now_local=now.astimezone(user_tz(user)),
            q=query(sc, now),
