def notes(user, a, b):
    return c.execute(sa.select(n.c.delivered_at, n.c.kind, n.c.body).where(n.c.user_id==user, n.c.delivered_at>=a, n.c.delivered_at<=b).order_by(n.c.delivered_at)).all()
