print("RECOVERY aino/maya/arjun:")
for u in ("aino","maya","arjun"):
    for r in rows(u,"RECOVERY_NOT_WORTH_SAYING"):
        ns = notes(u, r["evaluated_at"]-36*H, r["evaluated_at"]+2*H)
