print("BELOW_RELEVANCE aino (with fired):")
k=0
for r in rows("aino","BELOW_RELEVANCE"):
    fired=[t.get("values",{}).get("fired") for t in r["trace"] if t.get("layer")=="D1"]
    if fired and fired[0]:
        ns = notes("aino", r["evaluated_at"]-12*H, r["evaluated_at"]+12*H)
        print(" ", f"{r['evaluated_at']:%m-%d %H:%M}", fired, r["reason"][:60], len(ns)); k+=1
    if k>6: break
print("Meera sent while Arjun not:")
for r in c.execute(sa.select(d).where(d.c.user_id=="meera", d.c.outcome=="sent", d.c.replay_run=="demo").order_by(d.c.evaluated_at)).mappings():
    a = c.execute(sa.select(d.c.outcome, d.c.reason_code).where(d.c.user_id=="arjun", d.c.evaluated_at==r["evaluated_at"], d.c.replay_run=="demo")).first()
    an = notes("arjun", r["evaluated_at"]-12*H, r["evaluated_at"]+12*H)
    if a and a[0] != "sent" and r["evaluated_at"].astimezone().hour and not an:
        print(" ", f"{r['evaluated_at']:%m-%d %H:%M}", r["reason_code"], "| arjun:", a[1])
EOF

